     3	import java.math.RoundingMode;
     4	
     5	import br.com.loja.common.ApiException;
     6	import br.com.loja.common.ErrorCode;
     7	
     8	/** Entrega cotada numa transportadora externa; o prazo ganha os dias extras de despacho da região. */
     9	class CarrierShipping implements ShippingOption {
    10	
    11	    private final String code;
    12	    private final String carrierService;
    13	    private final CarrierGateway gateway;
    14	
    15	    CarrierShipping(String code, String carrierService, CarrierGateway gateway) {
    16	        this.code = code;
    17	        this.carrierService = carrierService;
    18	        this.gateway = gateway;
    19	    }
    20	
    21	    @Override
    22	    public String code() {
    23	        return code;
    24	    }
    25	
    26	    @Override
    27	    public ShippingQuote quote(ShippingRequest request) {
    28	        long grams = request.weightKg().movePointRight(3).setScale(0, RoundingMode.HALF_UP).longValueExact();
    29	        try {
    30	            CarrierGateway.CarrierQuote quote = gateway.quote(request.zipCode(), grams, carrierService);
    31	            return new ShippingQuote(quote.price(), quote.days() + request.region().carrierExtraDays());
    32	        } catch (CarrierGateway.ZipNotServedException e) {
    33	            throw new ApiException(ErrorCode.SHIPPING_METHOD_UNAVAILABLE);
    34	        } catch (CarrierGateway.CarrierDownException e) {
    35	            throw new ApiException(ErrorCode.CARRIER_UNAVAILABLE);
    36	        }
    37	    }
    38	}
