     1	package br.com.loja.payment;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.MathContext;
     5	import java.math.RoundingMode;
     6	
     7	import org.springframework.stereotype.Component;
     8	
     9	import br.com.loja.common.ApiException;
    10	import br.com.loja.common.ErrorCode;
    11	import br.com.loja.common.Money;
    12	
    13	@Component
    14	class CreditCardPayment implements PaymentOption {
    15	
    16	    private static final int MAX_INSTALLMENTS = 12;
    17	    private static final int MAX_INTEREST_FREE = 3;
    18	    private static final BigDecimal MONTHLY_RATE = new BigDecimal("0.0199");
    19	    private static final MathContext PRECISION = new MathContext(34, RoundingMode.HALF_EVEN);
    20	
    21	    @Override
    22	    public String code() {
    23	        return "CREDIT_CARD";
    24	    }
    25	
    26	    @Override
    27	    public void validateInstallments(int installments) {
    28	        if (installments < 1 || installments > MAX_INSTALLMENTS) {
    29	            throw new ApiException(ErrorCode.INVALID_INSTALLMENTS);
    30	        }
    31	    }
    32	
    33	    @Override
    34	    public PaymentCharge charge(PaymentContext context) {
    35	        BigDecimal total = context.orderTotal();
    36	        int n = context.installments();
    37	        if (n <= MAX_INTEREST_FREE) {
    38	            return new PaymentCharge(total, Money.round(total.divide(BigDecimal.valueOf(n), PRECISION)));
    39	        }
    40	        // Tabela Price: parcela = total * i / (1 - (1 + i)^-n)
    41	        BigDecimal growth = BigDecimal.ONE.add(MONTHLY_RATE).pow(n, PRECISION);
    42	        BigDecimal installment = Money.round(total.multiply(MONTHLY_RATE).multiply(growth)
    43	                .divide(growth.subtract(BigDecimal.ONE), PRECISION));
    44	        return new PaymentCharge(installment.multiply(BigDecimal.valueOf(n)), installment);
    45	    }
    46	}
