    31	/** Calcula o resumo da compra. É a única fonte dos valores, tanto do resumo quanto do pedido registrado. */
    32	@Service
    33	public class CheckoutService {
    34	
    35	    private static final String COUPON_CAP_RATE = "0.30";
    36	
    37	    private final ProductRepository products;
    38	    private final OrderRepository orders;
    39	    private final Map<String, ShippingOption> shippingOptions;
    40	    private final Map<String, Coupon> coupons;
    41	    private final Map<String, ClubTier> tiers;
    42	    private final Map<String, PaymentOption> paymentOptions;
    43	
    44	    CheckoutService(ProductRepository products, OrderRepository orders, List<ShippingOption> shippingOptions,
    45	                    List<Coupon> coupons, List<ClubTier> tiers, List<PaymentOption> paymentOptions) {
    46	        this.products = products;
    47	        this.orders = orders;
    48	        this.shippingOptions = index(shippingOptions, ShippingOption::code);
    49	        this.coupons = index(coupons, Coupon::code);
    50	        this.tiers = index(tiers, ClubTier::code);
    51	        this.paymentOptions = index(paymentOptions, PaymentOption::code);
    52	    }
    53	
    54	    public OrderSummary summarize(CheckoutRequest request) {
    55	        validateStructure(request);
    56	        List<CartLine> lines = loadLines(request.items());
    57	
    58	        ClubTier tier = find(tiers, request.clubTier(), ErrorCode.INVALID_CLUB_TIER);
    59	        Region region = Region.parse(request.region()).orElseThrow(() -> new ApiException(ErrorCode.INVALID_REGION));
    60	        String zip = request.zipCode();
    61	        if (zip == null || !zip.matches("\\d{8}")) {
    62	            throw new ApiException(ErrorCode.INVALID_ZIP_CODE);
    63	        }
    64	        ShippingOption shipping = find(shippingOptions, request.shippingMethod(), ErrorCode.INVALID_SHIPPING_METHOD);
    65	
    66	        BigDecimal subtotal = lines.stream().map(CartLine::total).reduce(Money.ZERO, BigDecimal::add);
    67	        BigDecimal weight = lines.stream()
    68	                .map(l -> l.product().weightKg().multiply(BigDecimal.valueOf(l.quantity())))
    69	                .reduce(BigDecimal.ZERO, BigDecimal::add);
    70	        ShippingQuote quote = shipping.quote(new ShippingRequest(zip, region, weight));
    71	        BigDecimal shippingCost = tier.waivesFreight() && shipping.freightWaivableByClub() ? Money.ZERO
    72	                : quote.cost();
    73	
    74	        BigDecimal couponDiscount = Money.ZERO;
    75	        if (request.coupon() != null) {
    76	            Coupon coupon = find(coupons, request.coupon(), ErrorCode.INVALID_COUPON);
    77	            boolean firstPurchase = !orders.hasPurchaseByCustomer(request.customer().cpf());
    78	            BigDecimal raw = coupon.discount(new CouponContext(lines, subtotal, shipping, shippingCost, firstPurchase));
    79	            couponDiscount = Money.round(raw).min(Money.percent(subtotal, COUPON_CAP_RATE));
    80	        }
    81	
    82	        PaymentOption payment = find(paymentOptions, request.paymentMethod(), ErrorCode.INVALID_PAYMENT_METHOD);
    83	        int installments = request.installments() == null ? 1 : request.installments();
    84	        payment.validateInstallments(installments);
    85	
    86	        BigDecimal insurance = region.insuranceFor(subtotal);
    87	        BigDecimal orderTotal = subtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
    88	        payment.validateAvailability(orderTotal);
    89	        PaymentCharge charge = payment.charge(new PaymentContext(orderTotal, installments, request.coupon() != null));
    90	
    91	        return new OrderSummary(subtotal, couponDiscount, shippingCost, quote.days(), insurance,
    92	                charge.finalTotal().subtract(orderTotal), charge.finalTotal(), installments,
    93	                charge.installmentAmount(), tier.credit(subtotal), tier.gift(subtotal));
    94	    }
    95	
    96	    private void validateStructure(CheckoutRequest request) {
    97	        if (request == null || request.items() == null || request.items().isEmpty()
    98	                || request.customer() == null || isBlank(request.customer().cpf())
    99	                || isBlank(request.customer().email())) {
   100	            throw new ApiException(ErrorCode.INVALID_ORDER);
   101	        }
   102	        Set<String> seen = new HashSet<>();
   103	        for (CheckoutRequest.Item item : request.items()) {
   104	            if (item == null || isBlank(item.sku()) || item.quantity() == null || item.quantity() <= 0
   105	                    || !seen.add(item.sku())) {
   106	                throw new ApiException(ErrorCode.INVALID_ORDER);
   107	            }
   108	        }
   109	    }
   110	
   111	    private List<CartLine> loadLines(List<CheckoutRequest.Item> items) {
   112	        Map<String, Product> found = products.findAllBySkus(items.stream().map(CheckoutRequest.Item::sku).toList())
   113	                .stream().collect(Collectors.toMap(Product::sku, Function.identity()));
   114	        if (items.stream().anyMatch(i -> !found.containsKey(i.sku()))) {
   115	            throw new ApiException(ErrorCode.UNKNOWN_PRODUCT);
   116	        }
   117	        if (found.values().stream().anyMatch(Product::discontinued)) {
   118	            throw new ApiException(ErrorCode.PRODUCT_DISCONTINUED);
   119	        }
   120	        if (items.stream().anyMatch(i -> found.get(i.sku()).stock() < i.quantity())) {
   121	            throw new ApiException(ErrorCode.INSUFFICIENT_STOCK);
   122	        }
   123	        return items.stream().map(i -> new CartLine(found.get(i.sku()), i.quantity())).toList();
   124	    }
   125	
   126	    private static boolean isBlank(String s) {
   127	        return s == null || s.isBlank();
   128	    }
   129	
   130	    private static <T> T find(Map<String, T> registry, String code, ErrorCode error) {
   131	        T found = code == null ? null : registry.get(code);
   132	        if (found == null) {
   133	            throw new ApiException(error);
   134	        }
   135	        return found;
   136	    }
   137	
   138	    private static <T> Map<String, T> index(List<T> beans, Function<T, String> code) {
   139	        Map<String, T> map = new LinkedHashMap<>();
   140	        beans.forEach(b -> map.put(code.apply(b), b));
   141	        return map;
   142	    }
   143	}
