    21	package br.com.loja.order;
    22	
    23	import java.time.Clock;
    24	import java.time.Duration;
    25	import java.time.Instant;
    26	import java.time.temporal.ChronoUnit;
    27	import java.util.List;
    28	import java.util.UUID;
    29	
    30	import org.springframework.dao.DuplicateKeyException;
    31	import org.springframework.http.HttpStatus;
    32	import org.springframework.stereotype.Service;
    33	import org.springframework.transaction.PlatformTransactionManager;
    34	import org.springframework.transaction.support.TransactionTemplate;
    35	
    36	import br.com.loja.catalog.ProductRepository;
    37	import br.com.loja.checkout.CheckoutRequest;
    38	import br.com.loja.checkout.CheckoutService;
    39	import br.com.loja.checkout.OrderSummary;
    40	import br.com.loja.common.ApiException;
    41	import br.com.loja.common.ErrorCode;
    42	import br.com.loja.customer.CustomerRepository;
    43	
    44	@Service
    45	public class OrderService {
    46	
    47	    private static final String OK = "OK";
    48	    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);
    49	
    50	    private final CheckoutService checkout;
    51	    private final OrderRepository orders;
    52	    private final ProductRepository products;
    53	    private final CustomerRepository customers;
    54	    private final List<OrderEventListener> listeners;
    55	    private final Clock clock;
    56	    private final TransactionTemplate tx;
    57	
    58	    OrderService(CheckoutService checkout, OrderRepository orders, ProductRepository products,
    59	                 CustomerRepository customers, List<OrderEventListener> listeners, Clock clock,
    60	                 PlatformTransactionManager transactionManager) {
    61	        this.checkout = checkout;
    62	        this.orders = orders;
    63	        this.products = products;
    64	        this.customers = customers;
    65	        this.listeners = listeners;
    66	        this.clock = clock;
    67	        this.tx = new TransactionTemplate(transactionManager);
    68	    }
    69	
    70	    public Order create(CheckoutRequest request) {
    71	        OrderSummary summary = checkout.summarize(request);
    72	        List<OrderItem> items = request.items().stream()
    73	                .map(i -> new OrderItem(i.sku(), i.quantity())).toList();
    74	        Order order = new Order(UUID.randomUUID().toString(), request.customer().cpf(),
    75	                OrderStatus.AWAITING_PAYMENT, Instant.now(clock).truncatedTo(ChronoUnit.SECONDS), summary, items,
    76	                null, null, null);
    77	        try {
    78	            tx.executeWithoutResult(s -> customers.createIfAbsent(request.customer().cpf(), request.customer().email()));
    79	        } catch (DuplicateKeyException e) {
    80	            // outra máquina criou o mesmo cliente agora há pouco: está tudo certo
    81	        }
    82	        tx.executeWithoutResult(s -> orders.insert(order));
    83	        return order;
    84	    }
    85	
    86	    public Order get(String id) {
    87	        return orders.findById(id).orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND));
    88	    }
    89	
    90	    private record PaymentResult(Order order, ErrorCode error) {
    91	    }
    92	
    93	    public Order confirmPayment(String id, String transactionId, String paidAtText) {
    94	        PaymentResult result = tx.execute(s -> processPayment(id, transactionId, paidAtText));
    95	        if (result.error() != null) {
    96	            throw new ApiException(result.error(), HttpStatus.CONFLICT);
    97	        }
    98	        return result.order();
    99	    }
   100	
   101	    private PaymentResult processPayment(String id, String transactionId, String paidAtText) {
   102	        Order order = lock(id);
   103	        Instant paidAt = parseInstant(paidAtText);
   104	        if (transactionId == null || transactionId.isBlank() || paidAt == null) {
   105	            throw new ApiException(ErrorCode.INVALID_ORDER);
   106	        }
   107	        if (transactionId.equals(order.paymentTransactionId())) {
   108	            return outcomeOf(order, order.paymentOutcome());
   109	        }
   110	        requireMove(order, OrderStatus.PAID);
   111	
   112	        if (paidAt.isAfter(order.createdAt().plus(PAYMENT_WINDOW))) {
   113	            return failPayment(order, transactionId, ErrorCode.ORDER_EXPIRED);
   114	        }
   115	        if (!products.reserve(order.items())) {
   116	            return failPayment(order, transactionId, ErrorCode.INSUFFICIENT_STOCK);
   117	        }
   118	        orders.recordPayment(id, transactionId, OK, OrderStatus.PAID);
   119	        Order paid = get(id);
   120	        listeners.forEach(l -> l.onPaid(paid));
   121	        return new PaymentResult(paid, null);
   122	    }
   123	
   124	    private PaymentResult failPayment(Order order, String transactionId, ErrorCode error) {
   125	        orders.recordPayment(order.id(), transactionId, error.name(), OrderStatus.CANCELLED);
   126	        Order cancelled = get(order.id());
   127	        listeners.forEach(l -> l.onCancelled(cancelled, false));
   128	        return new PaymentResult(cancelled, error);
   129	    }
   130	
   131	    private static PaymentResult outcomeOf(Order order, String outcome) {
   132	        return new PaymentResult(order, OK.equals(outcome) ? null : ErrorCode.valueOf(outcome));
   133	    }
   134	
   135	    public Order ship(String id, String trackingCode) {
   136	        return tx.execute(s -> {
   137	            Order order = lock(id);
   138	            if (trackingCode == null || trackingCode.isBlank()) {
   139	                throw new ApiException(ErrorCode.INVALID_ORDER);
   140	            }
   141	            requireMove(order, OrderStatus.SHIPPED);
   142	            orders.recordShipment(id, trackingCode);
   143	            Order shipped = get(id);
   144	            listeners.forEach(l -> l.onShipped(shipped));
   145	            return shipped;
   146	        });
   147	    }
   148	
   149	    public Order deliver(String id) {
   150	        return tx.execute(s -> {
   151	            Order order = lock(id);
   152	            requireMove(order, OrderStatus.DELIVERED);
   153	            orders.updateStatus(id, OrderStatus.DELIVERED);
   154	            return get(id);
   155	        });
   156	    }
   157	
   158	    public Order cancel(String id) {
   159	        return tx.execute(s -> {
   160	            Order order = lock(id);
   161	            requireMove(order, OrderStatus.CANCELLED);
   162	            boolean wasPaid = order.status() == OrderStatus.PAID;
   163	            if (wasPaid) {
   164	                products.release(order.items());
   165	            }
   166	            orders.updateStatus(id, OrderStatus.CANCELLED);
   167	            Order cancelled = get(id);
   168	            listeners.forEach(l -> l.onCancelled(cancelled, wasPaid));
   169	            return cancelled;
   170	        });
   171	    }
   172	
   173	    private Order lock(String id) {
   174	        return orders.findByIdForUpdate(id).orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND));
   175	    }
   176	
   177	    private static void requireMove(Order order, OrderStatus target) {
   178	        if (!order.status().canMoveTo(target)) {
   179	            throw new ApiException(ErrorCode.OPERATION_NOT_ALLOWED);
   180	        }
   181	    }
   182	
   183	    private static Instant parseInstant(String text) {
   184	        try {
   185	            return text == null ? null : Instant.parse(text);
   186	        } catch (java.time.format.DateTimeParseException e) {
   187	            return null;
   188	        }
   189	    }
   190	}
