   124	    private PaymentResult failPayment(Order order, String transactionId, ErrorCode error) {
   125	        orders.recordPayment(order.id(), transactionId, error.name(), OrderStatus.CANCELLED);
   126	        Order cancelled = get(order.id());
   127	        listeners.forEach(l -> l.onCancelled(cancelled, false));
   128	        return new PaymentResult(cancelled, error);
   129	    }
