   149	    public Order deliver(String id) {
   150	        return tx.execute(s -> {
   151	            Order order = lock(id);
   152	            requireMove(order, OrderStatus.DELIVERED);
   153	            orders.updateStatus(id, OrderStatus.DELIVERED);
   154	            return get(id);
   155	        });
   156	    }
   157	
   158	    public Order cancel(String id) {
   159	        return tx.execute(s -> {
   160	            Order order = lock(id);
   161	            requireMove(order, OrderStatus.CANCELLED);
   162	            boolean wasPaid = order.status() == OrderStatus.PAID;
   163	            if (wasPaid) {
   164	                products.release(order.items());
   165	            }
   166	            orders.updateStatus(id, OrderStatus.CANCELLED);
   167	            Order cancelled = get(id);
   168	            listeners.forEach(l -> l.onCancelled(cancelled, wasPaid));
   169	            return cancelled;
   170	        });
   171	    }
